#include <iostream>
#include <vector>
using namespace std;

template <typename T>
class Pouch {
public:
    void put(T x) { goods.push_back(x); }
    int count() { return goods.size(); }
    T at(int i) { return goods[i]; }
private:
    vector<T> goods;
};

int main() {
    int n = 0;
    cin >> n;

    Pouch<int> p;
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        p.put(x);
    }

    cout << p.count() << endl;
    cout << p.at(0) << endl;
    return 0;
}
